// カード効果のアクション（効果が実際に何をするか）。
// `type.ts` の肥大化（丸読みで約16万トークン）を避けるため 2026-09-12 に切り出した。
// import 側は従来どおり `type.ts` から読めばよい（`type.ts` が re-export している）。

import type {
    AuraCounter,
    BattleState,
    CardInstance,
    CardType,
    Color,
    EffectCounter,
    EndStepLock,
    FamilyFilter,
    GameAction,
    GameState,
    Keyword,
    LevelDef,
    PendingChoice,
    PlayerId,
    PlayerState,
    PlayerView,
    TargetFilter,
    TriggerEvent,
} from "../type"

export type EffectAction =
    | { type: "draw"; count: number; side?: "own" | "both"; costSkipCoreStep?: true; countCounter?: EffectCounter; costDestroyOwnFamily?: FamilyFilter; costSacrificeChosen?: true } // countCounter指定時はcountを無視しEffectCounterの値を枚数として使う（0ならログのみ。BS12-053オオヅツナナフシ：「相手の手札と同じ枚数」＝"opponentHand"）。costDestroyOwnFamily指定時は指定系統の自分のスピリット1体を破壊することがコスト（summonFromHandFree.costDestroyOwnFamilyと同型。候補が無ければ不発＝COST_MODEL.md §1、候補2体以上ならプレイヤーが選ぶ＝§2。costSacrificeChosenは選択の再入用の内部フラグ。BS13-X02蛇皇神帝アスクレピオーズ：「系統：「星魂」を持つ自分のスピリット1体を破壊することで、自分はデッキから3枚ドローする」） // 自分がデッキから引く（side:"both"指定時は自分→相手の順で両者が引く。省略時=own＝従来どおり自分のみ。BS03巨猫ブリンクス：お互いドロー）。// costSkipCoreStep指定時は「ボイドからコアをリザーブに置かないことで」＝そのコアステップのコア置きを支払いに使う。GameState.coreStepSkipped を立ててから引く（step.beforeStepAction と対で使う。BS10-087戦場に息づく命）
    | { type: "destroyCostsEachOne"; costs: number[] } // 指定コスト**ごとに1体ずつ**相手のスピリットを破壊する（コスト3から1体・コスト4から1体＝計2体。片方しかいなければその1体だけ。2026-08-14 ユーザー確認。BS09-052フォレスト・ゴレム）
    | { type: "destroy"; filter?: TargetFilter; count: number; countCounter?: EffectCounter; countPerOpponentTrashMagicColors?: boolean; anySide?: true; excludeTarget?: true; chooserIsTarget?: true; drawPerDestroyed?: true; thenDrawFixed?: number; lowestCost?: true; costDestroyOwnSpirit?: true; costSacrificeChosen?: true; costDiscardOwnBurst?: true } // costDiscardOwnBurst指定時は自分のバースト1つを破棄（トラッシュへ）することがコスト（bpBuff.costDiscardOwnBurstと同型。対象条件を満たす相手のスピリットが1体もいなければ不発＝COST_MODEL.md §1。docs/design/BURST.md。BS14-015トウダーLv2） // thenDrawFixed指定時は、破壊処理を解決した後（「その後」＝破壊数によらず、0体でも発火）、自分は固定枚数ドローする（drawPerDestroyedの比例版とは別軸。BS14-010皇牙獣キンタローグ・ベアー：「BP4000以下の相手のスピリット2体を破壊する。その後、自分はデッキから1枚ドローする」）。costDestroyOwnSpirit指定時は自分のスピリット1体を破壊することがコスト（対象条件を満たす相手のスピリットが1体もいなければ不発＝COST_MODEL.md §1。何を犠牲にするかは候補2体以上ならプレイヤーが選ぶ＝§2。costSacrificeChosenは選択の再入用の内部フラグ。BS13-051ズガネーク：「自分のスピリット1体を破壊することで、相手は、相手のスピリット1体を破壊する」＝chooserIsTargetと併用） // countCounter指定時はcountを無視しEffectCounterの値を破壊数として使う（0ならログのみ。exhaust.countCounterと同型。BS13-X01光龍騎神サジット・アポロドラゴン【合体中】Lv3：「このスピリットのブレイヴ1つにつき」）。lowestCost指定時は自動選択（非対話・自動）を実効BP最大でなく**コスト最小**にする（同コストは実効BP最大。BS12-084マーキュリーゴブレット「最もコストが低いスピリット1体」）。 drawPerDestroyed指定時は、**実際に破壊できた**1体につき1枚ドローする（「この効果で相手のスピリットを破壊したとき、自分はデッキから1枚ドローする」。BS11-006 獅龍皇子レオグルス）。「破壊されるかわりにフィールドに残る」で残った個体は数に入らない（destroyAll.drawPerDestroyed と同じ数え方で、destroyTargetsBatch の after を通す）
    // chooserIsTarget指定時は、**破壊される側（相手）が対象を選ぶ**（実行は発生源の持ち主の効果として解決する。exhaust/returnToDeckTopのchooserIsTargetと同型。BS10-101ハングドマン＝「相手は、相手のスピリット1体を破壊する」） // 相手スピリットを破壊（絞り込みは filter。省略=BP不問、selfがnullで self 相対BP指定ならno-op）。countPerOpponentTrashMagicColors指定時はcountを無視し、相手のトラッシュにあるマジックカードの色の種類数（重複除く）を対象数として使う（BS05超獣王ベヒードス）。anySide指定時は自分/相手どちらのスピリットも対象にできる（targetInstanceId優先、interactiveTargets時はrequestChoiceで両陣営から選択、非対話時は既存どおり実効BP最大を自動選択＝同値は相手側優先。BS01ランスラプトル等：修飾なしの「スピリット」）。excludeTarget指定時はtargetInstanceIdを「破壊する対象」ではなく「**除外する**対象」として扱う（誘発が渡すイベント対象を避ける。exhaust.excludeTargetと同型。BS06計画された場外乱闘Lv2：ブロックしたスピリット以外を破壊）
    | { type: "destroyOwnByFamilyThenWipeEnemy"; family: FamilyFilter } // 指定系統を持つ自分のスピリットすべてを破壊してから、相手のスピリットすべてを破壊する（BS04ストレートフラッシュ）
    | { type: "destroyDuplicateNames"; choosing?: true; keptIds?: string[] } // 相手のフィールドに同じカード名のスピリットが2体以上いるとき、カード名1つにつき1体だけ残して残りを破壊する（BS02マインドフレア）。**どれを残すかは持ち主が選ぶ**（効果文「カード名1つにつきスピリット1体ずつを残し」に主語が無いので発生源の持ち主。2026-08-24。非対話はフィールドの先頭側）。choosing / keptIds は重複するカード名を1つずつ聞くための内部フィールド（cards.jsonには書かない）
    | { type: "destroyAll"; filter?: TargetFilter; anySide?: boolean; drawPerDestroyed?: true; voidCoreToSelfPerDestroyed?: true } // filter に一致する相手スピリットを全破壊。anySide指定時は両陣営が対象（filter.colorExclude で色除外＝BS04魔龍帝ジークフリードLv3：赤以外のBP4000以下すべて。filter.rested と cost.max の組み合わせで「疲労状態のコストX以下すべて」＝BS05吸血女王カーミラ）。drawPerDestroyed指定時は実際に破壊できた数ぶん自分がドローする（BS08ドラゴンスクランブル）。voidCoreToSelfPerDestroyed指定時は実際に破壊できた数ぶん、ボイドからコアをself上に置く（selfがnullならno-op。X003D極帝龍騎ジーク・クリムゾン）
    | { type: "destroyByOwnFamilyCostSet"; familyFilter: FamilyFilter } // 自分の familyFilter 一致スピリット（self自身も含む。BS12-X06海賊王レヴィアダン「系統：「獣頭」を持つ自分のスピリットと同じコストの相手のスピリットすべてを破壊する」＝自身も獣頭・コスト7なので含む。2026-09-07ユーザー確認）の**コストの集合**（instAllCostsの和集合。同じコストを何体持っていても集合としては1つ）に、コストが一致する（instAllCostsのいずれかが集合に含まれる）相手のスピリットすべてを破壊する
    | { type: "selfBuff"; amount: number } // このスピリット自身をBP+（ターン終了時まで）
    | { type: "summonBurstCardFree" } // バースト専用（docs/design/BURST.md）：発動中のバーストのカード自身をコストを支払わずに召喚する（スピリット/ネクサスのみ。マジックには書かない）。維持コアはリザーブから置き、不足なら不発（他のFree系召喚と同じ方針）。召喚できたらバーストエリアは空になる
    | { type: "summonBurstCardFreeIfCoresAtLeast"; coresAtLeast: number } // burst.conditionは1つのburstエントリのactionを丸ごとゲートするため、「A。その後、条件を満たすときだけB。」のB側だけを条件付きにしたいとき用（kind:"sequence"のactionsに混ぜる）。自分のフィールド/リザーブ/トラッシュのコア合計がこれ未満なら何もしない（burstConditionMetのownCoresTotalAtLeastと同じ計算）。満たせばsummonBurstCardFreeへ委譲する（BS14-X03風の覇王ドルクス・ウシワカ：「相手のスピリット2体を疲労させる。その後、…コアが合計8個以上のとき、このスピリットカードを召喚する」の後半）
    | { type: "summonBurstCardFreeIfOwnNexusAtLeast"; nexusAtLeast: number } // summonBurstCardFreeIfCoresAtLeastのネクサス数版。自分のフィールドのネクサス数がnexusAtLeast未満なら何もしない（burstConditionMetのownNexusAtLeastと同じ計算）。満たせばsummonBurstCardFreeへ委譲する（BS14-064レボルシング・ゼヨン：「自分のトラッシュにある赤/紫/緑/青のネクサスカード1枚ずつを配置できる。その後、自分のフィールドにネクサスが3つ以上あるとき、このスピリットカードを召喚する」の後半＝配置は無条件、召喚だけが条件付き）
    | { type: "burstDestroyThenSummonSelf"; condition?: { ownLifeAtMost: number }; filter?: TargetFilter } // バースト専用：condition指定時、それを満たすときだけ破壊1体（filterで絞り込み）を解決する。**その後、条件の成否によらず必ず**summonBurstCardFreeと同じ処理でこのカード自身をコストを支払わずに召喚する（「この効果発揮後」＝発揮の有無を問わず後段は実行。破壊が復活確認等で中断した場合は再開後に召喚を続ける）。BS14-X01龍の覇王ジーク・ヤマト・フリード：「自分のライフが3以下のとき、BP15000以下の相手のスピリット1体を破壊する。この効果発揮後、このスピリットカードをコストを支払わずに召喚する」＝条件は破壊のほうだけに掛かる（2026-09-12ユーザー確認）。finishBurstActivationはこのtypeもsummonBurstCardFreeと同じ扱いにする
    | { type: "millSelfTopThenRefreshSelfIfFamily"; familyFilter: FamilyFilter } // 自分のデッキを上から1枚破棄し、それが指定系統（配列＝OR）を持つスピリットカードだったときだけ、このスピリット自身を回復させる（refreshSelfへ委譲。デッキが尽きていれば不発。BS14-X05神獣鳥アン・ズール：「そのカードが系統：「想獣」を持つスピリットカードのとき、このスピリットは回復する」）
    | { type: "revealTopToHandThenRefreshOwn"; colorFilter?: Color } // 自分のデッキを上から1枚オープンし、無条件に自分の手札に加える。それが指定色（省略時は色不問）のマジックカードだったときだけ、自分のスピリット1体を回復させる（refreshOneへ委譲。候補選択はrefreshOneと同じ）。デッキが尽きていれば不発（BS14-086運命のルーレット：「それが黄のマジックカードのとき自分のスピリット1体を回復させる。オープンしたカードは手札に加える」）
    | { type: "revealOwnBurstThenSortByType" } // BS14-053オリンピアの天使ハギト：自分のバースト1つ（あれば）をオープンする。マジックカードなら手札に戻し、それ以外はトラッシュへ破棄する（burstがnullなら不発）
    | { type: "setBurstFromHand" } // バースト専用：自分の手札にあるバースト効果（kind:"burst"）を持つカード1枚をセットする。setBurst（GameAction）と異なり**ターン1回制限を受けない**。候補2体以上ならinteractiveTargetsでkind:"card"の選択、非対話はコスト最大の1枚（決定的簡略化）
    | { type: "costSetBurstThenDraw"; count: number } // 「自分の手札にあるバースト効果を持つカード1枚をセットすることで、自分はデッキからcount枚ドローする」（COST_MODEL.md §1：セット＝コスト。setBurstFromHandと同じ候補選択・非対話簡略化で1枚セットし、**セットできたときだけ**続けてドローする。手札にバースト持ちが無ければ不発。X012R英雄皇ロード・ドラゴン・ドミニオン）
    | { type: "destroyNexus"; count: number; drawPerDestroyed?: number; discardOpponentPerDestroyed?: number; all?: boolean; side?: "opponent" | "both"; levelFilter?: number[]; colorFilter?: Color; chooseColor?: true; costDestroyOwnNexus?: true; costSacrificeChosen?: true; chooserIsTarget?: true }
    // chooserIsTarget指定時（count:1・side省略時のみ対応）は、**破壊される側（相手）が対象を選ぶ**（destroy.chooserIsTargetのネクサス版。
    // 解決は発生源の持ち主の効果として行う＝PendingChoice.actorPid。BS14-111エクスキューションデストロイ：「相手は、相手のネクサス1つを破壊する」） // costDestroyOwnNexus指定時は自分のネクサス1つ（コア最少、同数はフィールド先頭）を破壊することがコスト（summonFromHandFree.costDestroyOwnNexusと同型。破壊できる自分のネクサスが無い、または相手のネクサスが無ければ不発＝COST_MODEL.md §1。候補2体以上ならプレイヤーが選ぶ＝§2。costSacrificeChosenは選択の再入用の内部フラグ。BS13-045巨人船長イアソン：「自分のネクサス1つを破壊することで、相手のネクサス1つを破壊する」）。colorFilter指定時はその色を持つネクサスだけが対象（多色はOR。instHasColor）。chooseColor指定時は、まず**効果の使用者が色1色を指定し**、その色を colorFilter に載せて解決し直す（「色1色を指定する。指定した色のネクサスすべてを破壊する」。BS11-073 バスターハンマー）。非対話は「破壊できる数が最大になる色」を選ぶ（同数は red/purple/green/white/yellow/blue の順） // discardOpponentPerDestroyed指定時は、実際に破壊できたネクサス1つにつき相手の手札をその数だけ破棄させる（BS05鉄槌のオズワルドLv2） // 相手のネクサスを破壊（drawPerDestroyed指定時は実際に破壊できた数×ドロー）。all指定時はcountを無視し相手のネクサスすべてを破壊する（BS04風龍王フージャオス）。side指定時は破壊対象の陣営を切り替える（省略時はopponent＝従来どおり。BS01バスターファランクス＝both）。levelFilter指定時はcurrentLevelがこれに含まれるネクサスのみ対象（BS03バスターランス＝Lv1のみ）
    | { type: "returnSelfToHand" } // このスピリットを持ち主の手札に戻す
    | { type: "colorlessSelfThisBattle" } // 発揮した個体自身（self）を、このバトルの間だけ色とシンボルを無いものとして扱う（CardInstance.colorlessThisBattle。clearBattleでリセット。BS13-011/015/052：「このスピリットの色を無いものとして扱う」）
    | { type: "coreRemove"; count: number; dest?: "void" | "trash"; anySide?: true; countCounter?: EffectCounter; leaveAtLeast?: number; filter?: TargetFilter; drawIfEmptied?: true; all?: true } // drawIfEmptied指定時は、**この効果で**対象のコアが0個になったときに自分が1枚ドローする（BS10-066 騎士王蛇ペンドラゴン） // leaveAtLeast指定時は、対象のコアがこの数を下回らないところまでしか取り除かない（BS04王蛇の住処Lv2「この効果で相手のスピリット上のコアを0個にはできない」） // 対象スピリットのコアを持ち主のリザーブへ置く（dest:"void"指定時はリザーブでなくボイドへ＝消滅＝BS04ヴェノムショット。dest:"trash"指定時は持ち主のトラッシュへ＝BS12-012戦車皇ディルガン）。anySide指定時は自分/相手どちらのスピリットも対象にできる（targetInstanceId優先、interactiveTargets時はrequestChoiceで両陣営から選択、非対話時は既存どおり実効BP最大を自動選択＝同値は相手側優先。BS01ポイズンシュート：修飾なしの「スピリット」）。countCounter指定時はcountを無視しEffectCounterの値を除去枚数として使う（0ならログのみ。BS03巨人王ランドルフ：【粉砕】で破棄した枚数ぶん）。filter指定時は対象自動選択・明示ターゲットの両方にTargetFilterの絞り込みを適用する（BS08倒逆ピラミッド群：BP5000以下）。all指定時はcountを無視し、対象上のコアすべてを取り除く（BS13-X02蛇皇神帝アスクレピオーズLv3：「ブロックした相手のスピリットの[ソウルコア]以外のコアすべてをボイドに置く」＝[ソウルコア]は未実装のため無条件ですべて対象。discardOpponentTegamotoVoidCoresPerと同じ簡略化）
    | { type: "coreRemoveByPayingSelfCores"; filter?: TargetFilter; dest: "trash" } // 「このスピリットのコアを好きなだけ自分のトラッシュに置くことで、置いたコア1個につきfilter一致の相手スピリットのコアを1個相手のトラッシュに置く」（BS12-012戦車皇ディルガン：相手のアタックステップ開始時）。selfのコア数を0〜selfのコア数の**増減式選択**（PendingChoice.stepper。bpBuff.extraPerCoreToTrashと同型）で決め、支払った数nをcoreRemove（count:n, dest:"trash", filter）へ委譲する（装甲・効果耐性・維持コア割れの判定を1箇所に保つ）。非対話時は0個（何もしない）に倒す。selfのコアを払った結果維持コア割れなら消滅する
    | { type: "voidCoresFromField"; side: "own" | "opponent"; count: number; costOwnFieldCoresToVoid?: number } // 「自分のフィールドのコアcostOwnFieldCoresToVoid個をボイドに置くことで、sideのフィールドのコアcount個をボイドに置く」（BS12-015冥王神龍クロノ・ハデス：召喚時）。「フィールドのコア」はスピリット/ネクサス上のコアのみ（リザーブは含まない）。「〜することで」はコストなので、自分のフィールド合計がcostOwnFieldCoresToVoid以上・side側のフィールド合計がcount以上の**両方**を満たすときだけ発揮する（片方でも欠けたら不発。COST_MODEL.md §1）。どちらもコアの多い個体（スピリット/ネクサス）から順に自動で取る（決定的簡略化。範囲効果のため対象選択は挟まない）
    | { type: "bpBuff"; filter?: TargetFilter; amount: number; amountFromSelfBp?: true; scope?: "battle"; anySide?: true; extraPerCoreToTrash?: number; boostTargetInstanceId?: string; thenAddSymbolThisBattle?: { color: Color; count: number }; costExhaustFamily?: FamilyFilter; amountFromExhaustedCost?: true; costSacrificeChosen?: true; costMillSelfCount?: number; thenRefreshIfMilledFamily?: FamilyFilter; costDiscardOwnBurst?: true; costReturnSelfToHand?: true; costPaid?: true } // costReturnSelfToHand指定時は**このスピリット自身**を持ち主の手札に戻すことがコスト（negateLifeDamageFromTarget.costReturnSelfToHandと同型。対象になれる自分の他のスピリットが1体もいなければ不発＝COST_MODEL.md §1。costPaidは支払い済みの再入を示す内部専用フラグ。cards.jsonには書かない。BS14-X03風の覇王ドルクス・ウシワカ：「バトル終了時、このスピリットを手札に戻すことで、このターンの間、自分のスピリット1体をBP+3000する」） // costDiscardOwnBurst指定時は自分のバースト1つを破棄（トラッシュへ）することがコスト（docs/design/BURST.md。バーストがセットされていなければ不発＝COST_MODEL.md §1） // 器：costMillSelfCount指定時は自分のデッキを上からこの枚数だけ無条件に破棄することがコスト（lifeCharge.costMillSelfCountと同型。あるだけ処理してコストも払う＝COST_MODEL.md。デッキが尽きていても0枚破棄で成立する）。thenRefreshIfMilledFamily指定時は、その破棄で指定系統（配列＝OR。カード静的なfamilyで判定）を持つスピリットカードが1枚以上トラッシュに置かれたときだけ、続けて発生源自身（self）を回復させる（BS13-060トレス・ベルーガ【合体時】：「自分のデッキを上から6枚破棄することで、このスピリットをBP+6000する。この効果で自分のトラッシュに系統：「光導」を持つスピリットカードが1枚以上置かれたとき、このスピリットは回復する」）
